size_t bucket = argbucket;
const void *key = argkey;
const void *data = argdata;
size_t iter = 0;
const size_t max_iter = ckh->max_iterations;

while (iter < max_iter) {
    for (size_t slot = 0; slot < CKH_SLOTS; slot++) {
        if (ckh->tab[bucket + slot] == nullptr) {
            ckh->tab[bucket + slot] = key;
            ckh->data[bucket + slot] = data;
            return false;
        }
    }

    size_t evict_slot = iter % CKH_SLOTS;
    const void *evict_key = ckh->tab[bucket + evict_slot];
    const void *evict_data = ckh->data[bucket + evict_slot];

    ckh->tab[bucket + evict_slot] = key;
    ckh->data[bucket + evict_slot] = data;

    key = evict_key;
    data = evict_data;

    size_t h = ckh->hash(evict_key) >> (32 - ckh->lg_curbuckets);
    bucket = h & ((1 << ckh->lg_curbuckets) - 1);

    iter++;
}

return true;
// END_CODE

